from collections import deque
# use G currently filled from previous; regenerate original by resetting 4 to 1
A=[[1 if x==4 else x for x in row] for row in G]
R,C=len(A),len(A[0]); seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if A[r][c]==1 and (r,c) not in seen:
   q=[(r,c)]; seen.add((r,c)); comp=[]
   for x,y in q:
    comp.append((x,y))
    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
     nx,ny=x+dx,y+dy
     if 0<=nx<R and 0<=ny<C and A[nx][ny]==1 and (nx,ny) not in seen: seen.add((nx,ny)); q.append((nx,ny))
   comps.append(comp)
[(len(c),min(r for r,_ in c),max(r for r,_ in c),min(y for _,y in c),max(y for _,y in c)) for c in comps if len(c)<100]
